// P2 integration fixtures (backend-workflow-engineer). All data is SYNTHETIC. A "P2 world" is a transformation created
// through the API by a Transformation Lead (who thereby holds the derived TL assignment at the transformation,
// F-DG1-106), a Sponsor (SP) granted at the transformation, a Transformation Office user (TO, inherits from the
// organization; reviewer of evidence), a Workstream Lead (WL, contributor), a methodology admin and the read-only
// auditor (AUD). `makeG1Ready` completes every G1 required output through the API - including VERIFIED evidence - so
// the gate can be submitted and decided. The G1 decision in a test is a demo decision on synthetic data: it approves
// nothing real, and it is a PRODUCT gate (business approval), unrelated to the engineering gates DG0-DG7.
import { expect } from "vitest";
import {
  call,
  createUser,
  grant,
  signIn,
  type RequestOptions,
  type Res,
  type Session,
  type TestApi,
  type World,
} from "./harness.ts";

export const ifm = (v: number | string): Record<string, string> => ({ "if-match": `"${v}"` });

/**
 * P3 (ADR-0021 §8; REQ-PB-022, B0032): approving G1 needs the three leadership agreement confirmations. Every test that
 * approves G1 sends them (a synthetic demo decision; it approves nothing real).
 */
export const G1_AGREEMENTS = Object.freeze({ problem: true, baseline: true, materialValuePools: true });

export interface P2World {
  readonly transformationId: string;
  readonly lead: { id: string; session: Session };
  readonly sponsor: { id: string; session: Session };
  readonly office: { id: string; session: Session };
  readonly contributor: { id: string; session: Session };
  readonly auditor: { id: string; session: Session };
  readonly methodologyAdmin: { id: string; session: Session };
}

type Caller = (method: string, url: string, opts?: RequestOptions) => Promise<Res>;

/** Creates a P2 world on BU a1 of org A. `send` lets the contract test route calls through its mirror check. */
export async function setupP2World(api: TestApi, w: World, send?: Caller): Promise<P2World> {
  const req: Caller = send ?? ((m, u, o) => call(api.app, m, u, o));
  const lead = await createUser(api.db, w.orgA.id);
  const sponsor = await createUser(api.db, w.orgA.id);
  const contributor = await createUser(api.db, w.orgA.id);
  const methodologyAdmin = await createUser(api.db, w.orgA.id);
  await grant(api.db, w.grantor.id, lead.id, "TL", { type: "business_unit", id: w.a1 }, w.orgA.id);
  await grant(
    api.db,
    w.grantor.id,
    methodologyAdmin.id,
    "ADM_METHOD",
    { type: "organization", id: w.orgA.id },
    w.orgA.id,
  );
  const leadSession = await signIn(api.app, lead.subject);
  const t = await req("POST", "/api/v1/transformations", {
    session: leadSession,
    body: { businessUnitId: w.a1, name: "Synthetic P2 transformation", mode: "end_to_end" },
  });
  expect(t.status, JSON.stringify(t.body)).toBe(201);
  const transformationId = (t.body as { id: string }).id;
  await grant(api.db, w.grantor.id, sponsor.id, "SP", { type: "transformation", id: transformationId }, w.orgA.id);
  await grant(api.db, w.grantor.id, contributor.id, "WL", { type: "transformation", id: transformationId }, w.orgA.id);
  return {
    transformationId,
    lead: { id: lead.id, session: leadSession },
    sponsor: { id: sponsor.id, session: await signIn(api.app, sponsor.subject) },
    office: { id: w.office.id, session: await signIn(api.app, w.office.subject) },
    contributor: { id: contributor.id, session: await signIn(api.app, contributor.subject) },
    auditor: { id: w.auditor.id, session: await signIn(api.app, w.auditor.subject) },
    methodologyAdmin: { id: methodologyAdmin.id, session: await signIn(api.app, methodologyAdmin.subject) },
  };
}

const ok = (res: Res, status: number, what: string) => {
  expect(res.status, `${what}: ${JSON.stringify(res.body).slice(0, 600)}`).toBe(status);
  return res.body as { id: string; version: number } & Record<string, unknown>;
};

/** Completes every G1 required output of the world's transformation through the API (synthetic data). */
// P5 slice B test fixtures (T-DG5-BE-D; p5-work-split §B.2). The `forms` key is platform-wide (one open draft per key,
// and new transformations are pinned to its newest published version), so suites never publish or draft `forms`
// itself: each test seeds its OWN synthetic published form_schema version under a unique key, as the migration owner
// would (origin 'seed', with the audit events the deferred guards require), and pins its own fixture transformation to
// it, as an approved migration would. Every value here is synthetic test data; nothing here is a business approval.
import { randomBytes } from "node:crypto";
import { createDb, insertAuditEvent, type Db } from "@mth/db";
import { v7 as uuidv7 } from "uuid";
import { createTransformationRow, uniq, type TestApi, type World } from "./harness.ts";

const SYSTEM = { actorType: "system" as const, actorUserId: null, source: "migration" as const };
const ownerDb = (api: TestApi): Db => createDb(api.owner);

export interface FormElementSeed {
  readonly elementType: "form" | "form_field";
  readonly stableKey: string;
  readonly origin?: "source" | "admin";
  readonly attributes: Record<string, unknown>;
}

/** A synthetic published form_schema version under a fresh key, with the given element rows. */
export async function seedFormsVersion(
  api: TestApi,
  elements: readonly FormElementSeed[] = [],
): Promise<{ id: string; key: string }> {
  const id = uuidv7();
  const key = `test-forms-${uniq("k").toLowerCase()}`;
  await ownerDb(api)
    .transaction()
    .execute(async (tx) => {
      await tx
        .insertInto("methodology_version")
        .values({
          id,
          key,
          version_no: 1,
          status: "published",
          title_en: "Synthetic form schema",
          title_ar: "نموذج تجريبي",
          source_document: "synthetic test fixture",
          source_sha256: null,
          definition: JSON.stringify({ schema: "mth.test/1", fixture: true }),
          content_sha256: randomBytes(32).toString("hex"),
          published_at: new Date(),
          config_kind: "form_schema",
          origin: "seed",
        })
        .execute();
      await insertAuditEvent(tx, SYSTEM, {
        action: "test.seed",
        recordType: "methodology_version",
        recordId: id,
        organizationId: null,
        newVersion: 1,
      });
      for (const e of elements) {
        const elementId = uuidv7();
        await tx
          .insertInto("methodology_element")
          .values({
            id: elementId,
            methodology_version_id: id,
            element_type: e.elementType,
            stable_key: e.stableKey,
            origin: e.origin ?? "admin",
            removed: false,
            ordinal: null,
            attributes: JSON.stringify(e.attributes),
          })
          .execute();
        await insertAuditEvent(tx, SYSTEM, {
          action: "test.seed",
          recordType: "methodology_element",
          recordId: elementId,
          organizationId: null,
          newVersion: 1,
        });
      }
    });
  return { id, key };
}

/**
 * A fixture transformation in org A / BU a1 with the DG2-DG4 starter structure (six seeded T01 rows among others),
 * optionally pinned to a form_schema version (as an approved migration would have left it). Returns its id and the id
 * of one seeded T01 diagnostic item.
 */
export async function formsTransformation(
  api: TestApi,
  w: World,
  createdBy: string,
  formsVersionId?: string,
): Promise<{ transformationId: string; t01: string }> {
  const transformationId = await createTransformationRow(api.db, w.orgA.id, w.a1, createdBy);
  await api.owner.query(`SELECT p4_instantiate_transformation($1::uuid, $2::uuid, 'fixture', 'api')`, [
    transformationId,
    createdBy,
  ]);
  if (formsVersionId !== undefined) {
    const pinId = uuidv7();
    await ownerDb(api)
      .transaction()
      .execute(async (tx) => {
        await tx
          .insertInto("transformation_config_pin")
          .values({
            id: pinId,
            organization_id: w.orgA.id,
            transformation_id: transformationId,
            kind: "form_schema",
            methodology_version_id: formsVersionId,
            pinned_by: createdBy,
            created_by: createdBy,
            updated_by: createdBy,
          })
          .execute();
        await insertAuditEvent(tx, SYSTEM, {
          action: "test.seed",
          recordType: "transformation_config_pin",
          recordId: pinId,
          organizationId: w.orgA.id,
          newVersion: 1,
        });
      });
  }
  const item = await api.db
    .selectFrom("diagnostic_item")
    .select("id")
    .where("transformation_id", "=", transformationId)
    .orderBy("id")
    .executeTakeFirstOrThrow();
  return { transformationId, t01: item.id };
}

/** The extension fields of T01 used across the slice B suites (synthetic). */
export const T01_FIELDS: readonly FormElementSeed[] = [
  {
    elementType: "form_field",
    stableKey: "T01.risk_score",
    attributes: { fieldType: "number", labelEn: "Risk score", scale: 2 },
  },
  {
    elementType: "form_field",
    stableKey: "T01.adoption",
    attributes: { fieldType: "percentage", labelEn: "Adoption" },
  },
  { elementType: "form_field", stableKey: "T01.budget", attributes: { fieldType: "currency", labelEn: "Budget" } },
  {
    elementType: "form_field",
    stableKey: "T01.channels",
    attributes: {
      fieldType: "choice",
      labelEn: "Channels",
      multiple: true,
      options: [
        { value: "retail", labelEn: "Retail", labelAr: "التجزئة" },
        { value: "online", labelEn: "Online", labelAr: "عبر الإنترنت" },
      ],
    },
  },
