      title: TITLE,
      description: null,
      owner_user_id: x.contributor.id,
      due_date: due,
      follow_up_date: null,
      status: "open",
      raid_entry_id: null,
      dependency_id: null,
      corrective_case_id: null,
      source_workshop_item_id: null,
      created_by: x.lead.id,
      updated_by: x.lead.id,
      version: 1,
    });
    const events = await auditOf(api.db, actionId);

