+    for (const entity of ["&lt;", "&gt;", "&quot;", "&#"]) expect(inbox.raw.body).not.toContain(entity);
+    console.log(
+      `PASS REQ-S16-030 XSS in rich text: ${XSS_PAYLOADS.length} payloads x 4 surfaces round-trip byte-identical`,
