// ------------------------------------------------------------------------------------------------ tests

describe("SQL injection (REQ-S16-030; ADR-0052 §11)", () => {
  it("a free-text body field (T03 gap) stores each payload as text and returns it byte-identical", async () => {
    for (const payload of SQLI_PAYLOADS) {
      const created = await send("POST", `${T()}/tom-gaps`, {
        session: p.lead.session,
        body: { dimensionCode: "technology", gap: payload },
      });
      expect(created.status, JSON.stringify(created.body)).toBe(201);
      storedWith.set(payload, created.body.id as string);
      const got = await send("GET", `${T()}/tom-gaps/${created.body.id}`, { session: p.lead.session });
      expect(got.status).toBe(200);
      expect(got.body.gap).toBe(payload);
      expect(got.raw.body).toContain(JSON.stringify(payload));
      // The list's text filter treats the payload as literal text: it finds exactly the row that carries it.
      const found = await send("GET", `${T()}/tom-gaps?q=${encodeURIComponent(payload)}`, { session: p.lead.session });
      expect(found.status).toBe(200);
      expect(idsOf(found.body)).toEqual([created.body.id]);
    }
    passed.add("body");
  });

  it("every free-text query parameter of the list and search operations: 200, no extra rows", async () => {
    const ops = listOperations();
    // The contract set (17 at contract 1.5.0-p6 + slices; listed below) must not silently shrink to nothing.
    expect(ops.length).toBeGreaterThanOrEqual(10);
    const stored = new Set(storedWith.values());
    const failures: string[] = [];
    const report: string[] = [];
    let probes = 0;
    for (const op of ops) {
      for (const param of op.freeText) {
        // The caller: the first of lead, ADM and office for whom a no-match query answers 200.
        const token = `zq${crypto.randomUUID().replace(/-/g, "").slice(0, 12)}`;
        let session: Session | null = null;
        let baseline: Body = null;
        for (const s of [p.lead.session, admin, p.office.session]) {
          const r = await send("GET", urlOf(op, { [param]: token }), { session: s });
          if (r.status === 200) {
            session = s;
            baseline = r.body;
            break;
          }
        }
        if (session === null) {
          failures.push(`${op.operationId}?${param}: no caller in this world gets 200 for a plain query`);
          continue;
        }
        const unfiltered = await send("GET", urlOf(op, {}), { session });
        for (const payload of SQLI_PAYLOADS) {
          probes += 1;
          const res = await send("GET", urlOf(op, { [param]: payload }), { session });
          if (res.status !== 200) {
            failures.push(`${op.operationId}?${param}=${payload}: ${res.status} ${res.body?.code}`);
            continue;
          }
          const words = wordsOf(payload);
          const plain =
            words.length >= 2 ? await send("GET", urlOf(op, { [param]: words }), { session }) : { status: 200, body: baseline };
          const allowed = new Set([...idsOf(baseline), ...(plain.status === 200 ? idsOf(plain.body) : []), ...stored]);
          const extra = idsOf(res.body).filter((id) => !allowed.has(id));
          if (extra.length > 0)
            failures.push(`${op.operationId}?${param}=${payload}: ${extra.length} extra row(s) ${extra.slice(0, 3)}`);
          report.push(
            `${op.operationId}?${param} "${payload}": ${idsOf(res.body).length} row(s) (unfiltered ${idsOf(unfiltered.body).length})`,
          );
        }
      }
    }
    expect(failures).toEqual([]);
    passed.add("query");
    console.log(`  ${report.join("\n  ")}`);
    console.log(
      `  operations: ${ops.map((o) => `${o.operationId}(${o.freeText.join(",")})`).join(", ")}; ${probes} probes`,
    );
  });

  it("audit_event still exists and still records writes", async () => {

